var kind string
var ct, nonce []byte
e := repo.DB.QueryRowContext(ctx, `SELECT kind,ciphertext,nonce FROM secrets WHERE probe_id=$1 AND id=$2`, probeID, id).Scan(&kind, &ct, &nonce)
if e == sql.ErrNoRows {

	return nil, ErrSecretNotFound
