if e != nil {
	return nil, e
}
aad := []byte("probe\x00" + probeID + "\x00" + id + "\x00" + kind)
pt, e := s.aead.Open(nil, nonce, ct, aad)
if e != nil {

		return nil, ErrSecretDecrypt
	}
	return pt, nil
}

